for skill_dir in skills_dir.iterdir():
    if skill_dir.is_dir():
        skill_md = skill_dir / 'SKILL.md'
        if skill_md.exists():
            try:
                with open(skill_md, 'r', encoding='utf-8') as f:
                    content = f.read()
                    skill_sizes.append((skill_dir.name, len(content)))
            except:
                skill_sizes.append((skill_dir.name, 0))

# Sort by size descending
skill_sizes.sort(key=lambda x: x[1], reverse=True)

print("=== LARGEST SKILLS (by content size) ===")
for name, size in skill_sizes[:10]:
    print(f"{name:30} {size:6,} chars")

print()
print("=== SKILLS THAT MIGHT NEED SPLITTING (>5000 chars) ===")
large_skills = [(name, size) for name, size in skill_sizes if size > 5000]
for name, size in large_skills:
    print(f"{name:30} {size:6,} chars")

print()
print("=== SKILLS THAT MIGHT BE CANDIDATES FOR MERGING ===")
# Look for skills with similar names or descriptions
skill_names = [name for name, _ in skill_sizes]
similar_pairs = []

# Check for common prefixes/suffixes
for i, name1 in enumerate(skill_names):
    for name2 in skill_names[i+1:]:
        # Simple similarity check
        if name1.lower() in name2.lower() or name2.lower() in name1.lower():
            if abs(len(name1) - len(name2)) < 10:  # Similar length
                similar_pairs.append((name1, name2))

if similar_pairs:
    print("Potentially similar skill names:")
    for name1, name2 in similar_pairs[:10]:  # Show first 10
